import { FetchResult, TransformResult } from './types';

export { TransformResult };

export async function transform(fetchResult: FetchResult): Promise<TransformResult> {
  await new Promise((resolve) => setTimeout(resolve, 10));

  let parsed: any;
  try {
    parsed = JSON.parse(fetchResult.data);
  } catch (e) {
    throw new Error(`JSON parse failure: ${(e as Error).message}`);
  }

  if (!parsed.name) {
    throw new Error('Missing required field: name');
  }

  return {
    id: parsed.id ?? Date.now(),
    slug: parsed.name.toLowerCase().replace(/\s+/g, '-'),
    sourceUrl: fetchResult.url,
    transformedAt: new Date().toISOString(),
  };
}

export function transformData(
  fetchResult: FetchResult,
  callback: (err: Error | null, result?: TransformResult) => void
): void;
export function transformData(fetchResult: FetchResult): Promise<TransformResult>;
export function transformData(
  fetchResult: FetchResult,
  callback?: (err: Error | null, result?: TransformResult) => void
): Promise<TransformResult> | void {
  if (callback) {
    transform(fetchResult)
      .then((res) => callback(null, res))
      .catch((err) => callback(err));
    return;
  }
  return transform(fetchResult);
}

import { TransformResult, LoadResult } from './types';

export { LoadResult };

export function loadRecord(
  tableName: string,
  record: TransformResult,
  callback: (err: Error | null, result?: LoadResult) => void
): void {
  setTimeout(() => {
    if (!tableName) {
      callback(new Error('Missing destination table name'));
      return;
    }
    if (record.id < 0) {
      callback(new Error(`Duplicate key violation in table ${tableName}: ${record.id}`));
      return;
    }
    callback(null, {
      insertedId: record.id,
      table: tableName,
      success: true,
    });
  }, 10);
}

export interface FetchResult {
  url: string;
  status: number;
  data: string;
}

export interface TransformResult {
  id: number;
  slug: string;
  sourceUrl: string;
  transformedAt: string;
}

export interface LoadResult {
  insertedId: number;
  table: string;
  success: boolean;
}

export interface PipelineConfig {
  url: string;
  tableName: string;
}

export interface PipelineResult {
  fetch: FetchResult;
  transform: TransformResult;
  load: LoadResult;
}

export class PipelineError extends Error {
  readonly stage?: string;
  readonly originalError?: Error;

  constructor(message: string, stage?: string, originalError?: Error) {
    super(message);
    this.name = 'PipelineError';
    this.stage = stage;
    this.originalError = originalError;
    if (originalError && !('cause' in this)) {
      this.cause = originalError;
    }
    Object.setPrototypeOf(this, new.target.prototype);
  }
}

